//! The row iterator of the tables from `#[bitfields(columns = ...)]`. Needs
//! the `alloc` feature.

use core::fmt;
use core::iter::FusedIterator;

/// Implemented by the tables that `#[bitfields(columns = ...)]` generates.
/// Not part of the public API.
pub trait Table {
    type Row;
    fn __len(&self) -> usize;
    fn __row(&self, index: usize) -> Self::Row;
}

/// The rows of `table`, for the generated `iter()`.
#[inline]
pub fn rows<T: Table>(table: &T) -> Rows<'_, T> {
    Rows { table, front: 0, back: table.__len() }
}

/// An iterator over the rows of a table generated by
/// `#[bitfields(columns = Name)]`, from `Name::iter()` or `for row in &table`.
/// See [Struct of arrays](crate#struct-of-arrays).
pub struct Rows<'a, T> {
    table: &'a T,
    front: usize,
    back: usize,
}

impl<T> Clone for Rows<'_, T> {
    #[inline]
    fn clone(&self) -> Self {
        Self { table: self.table, front: self.front, back: self.back }
    }
}

impl<T: Table> Iterator for Rows<'_, T> {
    type Item = T::Row;

    #[inline]
    fn next(&mut self) -> Option<T::Row> {
        if self.front == self.back {
            return None;
        }
        self.front += 1;
        Some(self.table.__row(self.front - 1))
    }

    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) {
        let n = self.back - self.front;
        (n, Some(n))
    }

    #[inline]
    fn nth(&mut self, n: usize) -> Option<T::Row> {
        self.front = self.front.saturating_add(n).min(self.back);
        self.next()
    }

    #[inline]
    fn count(self) -> usize {
        self.back - self.front
    }

    #[inline]
    fn last(mut self) -> Option<T::Row> {
        self.next_back()
    }
}

impl<T: Table> DoubleEndedIterator for Rows<'_, T> {
    #[inline]
    fn next_back(&mut self) -> Option<T::Row> {
        if self.front == self.back {
            return None;
        }
        self.back -= 1;
        Some(self.table.__row(self.back))
    }

    #[inline]
    fn nth_back(&mut self, n: usize) -> Option<T::Row> {
        self.back = self.back.saturating_sub(n).max(self.front);
        self.next_back()
    }
}

impl<T: Table> ExactSizeIterator for Rows<'_, T> {}

impl<T: Table> FusedIterator for Rows<'_, T> {}

impl<T> fmt::Debug for Rows<'_, T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Rows").field("remaining", &(self.back - self.front)).finish()
    }
}
